#!/usr/bin/env python3
"""Render self-contained HTML explanations of the conditional cis forecasts."""
from pathlib import Path
import pandas as pd,json,html
HERE=Path(__file__).resolve().parent
PRIMARY=HERE/'outputs/ct_cis_forecast_v1'
LAGGED=HERE/'outputs/ct_cis_forecast_lagged_v1'
STYLE='body{font:17px/1.55 system-ui,sans-serif;margin:40px auto;max-width:1150px;padding:0 24px;color:#24343b}h1,h2{line-height:1.2}img{max-width:100%;border:1px solid #ddd}table{border-collapse:collapse;width:100%;font-size:14px}th,td{padding:7px;border-bottom:1px solid #ddd;text-align:right}th:first-child,td:first-child{text-align:left}.note{padding:14px;background:#eef5f6;border-left:4px solid #187b89}code{font-size:14px}a{color:#08768b}'

def table(df,columns):
 q=df[columns].copy()
 for c in q:
  if c.startswith('improvement') or c.endswith('_low') or c.endswith('_high'):q[c]=(q[c]*100).map(lambda x:f'{x:+.3f}%')
 return q.to_html(index=False,escape=True)

def write(path,title,body):path.write_text('<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>'+html.escape(title)+'</title><style>'+STYLE+'</style></head><body><h1>'+html.escape(title)+'</h1>'+body+'</body></html>')

def main():
 p=pd.read_csv(PRIMARY/'forecast_pooled_metrics.csv');q=pd.read_csv(LAGGED/'forecast_pooled_metrics.csv')
 keep=['own_history','cis_history','distance_history','shuffled_history'];pp=p[(p.scope=='all_test_origins')&p.model.isin(keep)]
 protocol='''<h2>What was tested</h2><p>For each peak and celltype, the primary model predicts the next accessibility <b>change in CPM/hour</b>, not merely the highly autocorrelated future accessibility level. Features use observed counts from cell half A: current own accessibility, previous own slope, and optionally the current weighted Cicero-neighbor accessibility minus own accessibility. Outcomes are <code>(B[t+1] − B[t]) / Δt</code>, entirely from the independent cell half B. The experiment is repeated B→A.</p><p>Weights are positive Cicero scores, row normalized over neighbors; the diagonal is excluded. Missing-edge rows have zero coupling and do not enter connected-peak scores. Actual time gaps are used.</p><p>Forecast origins are 14, 16, and 19 hpf. At each origin, regressions use only earlier completed transitions; no future observations or six-stage fitted trajectories enter features, scaling, or coefficient fitting. Five chromosome folds keep each test chromosome out of model training. Separate celltype regressions use a fixed ridge penalty of 0.1 on standardized slopes under mean squared training loss. No penalty, cutoff, or model is selected using the test results.</p>'''
 limits='''<h2>Scope and interpretation</h2><p><b>The graph was learned using all cells and stages.</b> This is a conditional test of a fixed graph, not fully held-out graph estimation or prospective biological validation. Cell halves measure sampling reproducibility, not biological replication. Chromosome bootstrap bands measure block sampling sensitivity.</p><p>At Cicero ≥0.25, only 4,525 of 640,830 atlas peaks (0.706%) are connected; at ≥0.5, 807 (0.126%) are connected. These selected subsets differ, so thresholds cannot be ranked as if they evaluated the same peaks. This graph cannot currently support a whole-atlas explanation of root-to-branch flow.</p><p>Simultaneous co-accessibility does not establish temporal precedence. Neighboring peaks can also have different baseline CPM, so directly replacing a peak with a weighted neighbor mean is not automatically a future-state estimate. The own-history baseline controls current own level and recent trend. Negative results here do not exclude lineage-specific regulatory coupling or useful descriptive smoothing, but they do not support calling this weighted graph a predictive velocity model.</p>'''
 body='<div class="note"><b>Result:</b> Current weighted Cicero-neighbor accessibility did not improve held-out change forecasts. Adding the neighbor residual increased error by 0.126% versus own history at cutoff 0.25, and by 0.694% at cutoff 0.5. Even own history did not beat persistence (zero predicted change) over these three temporal tests.</div>'+protocol
 body+='<h2>Primary results</h2><img src="01_cis_future_change.png" alt="Cicero future change prediction compared with own history">'+table(pp,['threshold','model','improvement_vs_own_history','paired_own_low','paired_own_high','improvement_vs_persistence'])
 body+='<p>Positive percentages indicate lower squared-change error. Limits are paired 95% chromosome-bootstrap ranges, with losses aggregated over celltypes, intervals and both split directions before chromosome resampling.</p><h2>Benchmarks and coefficients</h2><img src="02_forecast_benchmarks.png" alt="All forecast benchmarks"><p>The unregularized previous slope and fixed diffusion baselines performed poorly. Diffusion uses β(Wx−x)/Δt for β=0.1,0.3,0.6,1.0; this is a sensitivity grid, not an optimized choice.</p><img src="03_cis_coupling_coefficients.png" alt="Learned coupling coefficients"><h2>Examples selected before the forecast intervals</h2><img src="04_training_selected_examples.png" alt="Training selected peak trajectories"><p>Examples were selected only from 10/12 hpf source-half measurements: two strong early increases and two strong early decreases, distinct peaks and celltypes, with at least 20 source counts across those first two stages. Later curves are displayed only after selection.</p>'
 body+=limits+'<h2>Controls and follow-up</h2><p>The distance control preserves chromosome, distance bin where available, edge-draw count and row weight mass, but does not match abundance or indegree. A separate feature permutation preserves current-abundance bins within chromosomes. No control is interpreted as a causal null.</p><p><a href="../ct_cis_forecast_lagged_v1/report.html">Exploratory follow-up: add recent changes in linked peaks.</a> This also failed to improve prediction.</p>'
 body+='<h2>Reproducible files</h2><ul>'+''.join(f'<li><a href="{n}">{n}</a></li>' for n in ['forecast_metrics.csv','forecast_pooled_metrics.csv','forecast_celltype_metrics.csv','forecast_chromosome_losses.csv','forecast_coefficients.csv','forecast_folds.json','forecast_predictions.h5','forecast_validation.json','training_selected_examples.csv'])+'</ul><p>Run <code>ct_cis_forecast.py</code> with the single-cell-base Python environment. Source pseudobulk and graph files are read-only; provenance and source signatures are recorded in the validation JSON.</p>'
 write(PRIMARY/'report.html','Can current Cicero neighbors forecast accessibility changes?',body)
 qq=q[q.scope=='all_test_origins']
 body='<div class="note"><b>Result:</b> Adding the recent weighted neighbor slope also did not help. Current-plus-lagged cis features increased error versus own history by 1.401% at cutoff 0.25 and 5.404% at cutoff 0.5. This is a post-primary exploratory extension, with all settings and models reported.</div>'+protocol
 body+='<h2>Additional feature</h2><p>The extra feature is the weighted mean of source-half neighbor rates during the immediately preceding interval: <code>W × (A[t] − A[t−1]) / previous Δt</code>. It uses no future observations. Models include neighbor current state alone, lagged neighbor change alone, and both together. Distance and shuffled controls include both features; permutation assignments are shared between current and lagged features to preserve their joint relationship. Own-history and current-cis baseline predictions match the primary files bitwise.</p><img src="01_lagged_cis_forecast.png" alt="Lagged cis forecast comparison">'
 body+=table(qq,['threshold','model','improvement_vs_own_history','own_history_low','own_history_high','improvement_vs_cis_current','improvement_vs_persistence'])
 body+='<h2>Celltypes</h2><img src="02_lagged_cis_celltypes.png" alt="All celltype-specific forecast comparisons"><p>Celltype results are descriptive and uncorrected. No favorable subtype was selected for a validation claim.</p>'+limits
 body+='<h2>Files</h2><ul>'+''.join(f'<li><a href="{n}">{n}</a></li>' for n in ['forecast_metrics.csv','forecast_pooled_metrics.csv','forecast_celltype_metrics.csv','forecast_chromosome_losses.csv','forecast_coefficients.csv','forecast_folds.json','forecast_predictions.h5','forecast_validation.json'])+'</ul><p>Run <code>ct_cis_forecast_lagged.py</code>; it imports the same train-only standardized regression helper as the primary experiment. <a href="../ct_cis_forecast_v1/report.html">Primary experiment report.</a></p>'
 write(LAGGED/'report.html','Do recent changes in Cicero neighbors predict future changes?',body)
if __name__=='__main__':main()
